<?php requireAdmin();$pending=[];foreach(['place'=>"SELECT COUNT(*) FROM member_places WHERE state='pending'",'trip'=>"SELECT COUNT(*) FROM member_trips WHERE pending_plan IS NOT NULL",'post'=>"SELECT COUNT(*) FROM network_posts WHERE state='pending'",'comment'=>"SELECT COUNT(*) FROM network_comments WHERE state='pending'",'translation'=>"SELECT COUNT(*) FROM network_submissions WHERE state='pending'"] as $kind=>$sql)$pending[$kind]=(int)socialQuery($sql)->fetchColumn();?>
<h2>מה ממתין לטיפול?</h2><div class="result-grid"><?php foreach(['place'=>'מקומות','trip'=>'מסלולים','post'=>'פרסומים','comment'=>'תגובות','translation'=>'תרגומים'] as $kind=>$label):?><a class="social-card" href="/KNISA/community/?state=pending&amp;type=<?=$kind?>"><?=e($label)?><strong><?=$pending[$kind]?></strong></a><?php endforeach?><a class="social-card" href="/KNISA/community/?view=history">דיווחים פתוחים<strong><?=(int)socialQuery("SELECT COUNT(*) FROM member_reports WHERE state='open'")->fetchColumn()?></strong></a></div><p>הספירות כוללות תוכן הדגמה. אלה משימות ניהול, לא מספר משתמשים או לקוחות.</p><div class="social-card"><h2>ייבוא ותקינות</h2><p><a href="/KNISA/model-files/">העלאת חבילה לבדיקה מקדימה</a> · <a href="/KNISA/maintenance/">בדיקות מצב מערכת</a> · <a href="/KNISA/community/?view=history#product-metrics">מדדי המוצר</a></p><p>ספירה היסטורית של ייבואים שנכשלו ושל תרגומים חסרים בכל הטיולים עדיין אינה נאספת במסך זה.</p></div><h2>פעולות ניהול אחרונות</h2><table><thead><tr><th>זמן UTC</th><th>סוג</th><th>פעולה</th></tr></thead><tbody><?php foreach(socialQuery('SELECT kind,action,created FROM member_moderation ORDER BY id DESC LIMIT 15') as $row):?><tr><td><?=gmdate('Y-m-d H:i',(int)$row['created'])?></td><td><?=e($row['kind'])?></td><td><?=e($row['action'])?></td></tr><?php endforeach?></tbody></table>
